// onchain-retention — the plan (task 014-41, deployment.md §10.3.1 / §10.6.1).
//
// ONE pass computes every job's window, validates it against the bounds the JOB carries, mints its
// ULID and freezes `startedAt`. Nothing downstream re-derives any of it: the row a job writes must
// name the period that job's own statement covered, and a second clock would let the two disagree.
//
// **A window out of range is REFUSED, never clamped** (§10.3.1). A clamped window deletes rows the
// operator asked to keep, and `retention_runs` would then record the clamped period as the requested
// one. So an invalid job carries `valid: false`, its statement deletes nothing, and its row is
// written with `outcome: 'failed'` and the rejected setting named in `detail_json`.
//
// **The NORMALIZED window is validated FIRST, because the two RAW maxima are defined in terms of
// it** (§10.3.1: "the maximum is the NORMALIZED window"). If it is itself out of range, the RAW
// bounds have no value to be measured against — so all three jobs refuse rather than one of them
// being measured against a number that was already rejected.
const DAY_MS = 86400000;
const params = $('Set Parameters').first().json;
const startedAt = Date.now();

// ULID, Crockford base32: 10 chars of epoch-ms + 16 of randomness (DB-SCHEMA §1.2 — the app
// generates ids, never the engine's autoincrement). Written out because a Code node has no library.
const B32 = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
function ulid(ms) {
  let time = '';
  let rest = ms;
  for (let i = 0; i < 10; i += 1) {
    time = B32[rest % 32] + time;
    rest = Math.floor(rest / 32);
  }
  let rand = '';
  for (let i = 0; i < 16; i += 1) rand += B32[Math.floor(Math.random() * 32)];
  return time + rand;
}

const asDays = (value) => (typeof value === 'number' && Number.isInteger(value) ? value : NaN);
// The RAW value is kept beside the parsed one. `NaN` serialises to `null` in JSON, so a detail line
// built from the parsed value would report a setting of `ninety` as `null` — and this record exists
// precisely to NAME the rejected setting to whoever has to change it.
const raw = {
  'diagnostics.purge': params.diagnosticsPurgeDays,
  'request_trace.raw_null': params.traceRawNullDays,
  'request_trace.purge': params.tracePurgeDays,
  'client_usage.purge': params.clientUsagePurgeDays,
};
const normalizedDays = asDays(params.tracePurgeDays);
const normalizedOk = normalizedDays >= 365 && normalizedDays <= 730;
const shown = (key) => JSON.stringify(raw[key]) ?? String(raw[key]);

const SPECS = [
  {
    job: 'diagnostics.purge',
    targetTable: 'onchain.diagnostics',
    days: asDays(params.diagnosticsPurgeDays),
    floor: 90,
    max: normalizedOk ? normalizedDays : null,
    maxName: 'the NORMALIZED window',
  },
  {
    job: 'request_trace.raw_null',
    targetTable: 'onchain.request_trace',
    days: asDays(params.traceRawNullDays),
    floor: 90,
    max: normalizedOk ? normalizedDays : null,
    maxName: 'the NORMALIZED window',
  },
  {
    job: 'request_trace.purge',
    targetTable: 'onchain.request_trace',
    days: normalizedDays,
    floor: 365,
    max: 730,
    maxName: '730 days, applied not measured',
  },
  {
    job: 'client_usage.purge',
    targetTable: 'onchain.client_usage',
    days: asDays(params.clientUsagePurgeDays),
    floor: 1095,
    max: 2190,
    maxName: '2190 days, applied not measured',
  },
];

const jobs = {};
const b64 = {};
for (const spec of SPECS) {
  const reasons = [];
  if (!Number.isFinite(spec.days)) {
    reasons.push(`window is ${shown(spec.job)}, not a whole number of days`);
  } else {
    if (spec.days < spec.floor) reasons.push(`window ${spec.days}d is below the floor of ${spec.floor}d`);
    if (spec.max === null) {
      reasons.push(
        `the NORMALIZED window (${shown('request_trace.purge')}) is itself out of its 365..730d ` +
          'range, so this job has no maximum to be measured against',
      );
    } else if (spec.days > spec.max) {
      reasons.push(`window ${spec.days}d is above the maximum of ${spec.max}d (${spec.maxName})`);
    }
  }
  const valid = reasons.length === 0;
  // The period is recorded even when the job refuses: it is what was ASKED for, and a row saying
  // "this was requested and refused" is the whole point of writing a failed row. `periodFrom` is 0 —
  // these jobs act on everything older than the cutoff, so the period opens at the epoch.
  const cutoff = Number.isFinite(spec.days) ? startedAt - spec.days * DAY_MS : startedAt;
  const descriptor = {
    id: ulid(startedAt),
    job: spec.job,
    targetTable: spec.targetTable,
    startedAt,
    periodFrom: 0,
    periodTo: cutoff,
    valid,
    // `null` when the job refuses: the statement binds this, and a null cutoff cannot match a row
    // even if the guard above were removed. Two independent reasons nothing is deleted.
    cutoff: valid ? cutoff : null,
    detail: JSON.stringify({
      // The setting AS CONFIGURED, not as parsed — see `shown` above.
      requestedSetting: raw[spec.job],
      requestedDays: Number.isFinite(spec.days) ? spec.days : null,
      floorDays: spec.floor,
      maxDays: spec.max,
      maxSource: spec.maxName,
      refused: reasons,
      note: 'periodFrom=0 — this job acts on everything older than periodTo',
    }),
  };
  jobs[spec.job] = descriptor;
  b64[spec.job] = Buffer.from(JSON.stringify(descriptor)).toString('base64');
}

return [{ json: { startedAt, jobs, b64 } }];

// onchain-retention — the `retention_runs` row for `diagnostics.purge`.
//
// Built HERE, in the same pass as the statement above, because a row written by a later pass cannot
// name the period that deletion covered. `rows_affected` is read from the statement's own single
// result row; the id, the period and `startedAt` come from the plan, so both halves of the pair
// describe one act.
//
// Base64, bound as ONE `$1` parameter: `queryReplacement` is positional CSV, so a value holding a
// comma breaks it and an empty value silently shifts every later `$N`. Base64 has neither, and it is
// driver-bound rather than interpolated — the SQLi shape vdd-multi caught on the snapshotter.
const plan = $('Plan jobs').first().json;
const job = plan.jobs['diagnostics.purge'];
const result = $input.first().json;
const rowsAffected = Number(result?.rows_affected ?? 0);

const row = {
  id: job.id,
  job: job.job,
  target_table: job.targetTable,
  period_from: job.periodFrom,
  period_to: job.periodTo,
  rows_affected: Number.isFinite(rowsAffected) ? rowsAffected : 0,
  started_at: job.startedAt,
  finished_at: Date.now(),
  // A run that deleted nothing still writes `ok`: "nothing to delete" and "the job did not run" are
  // different facts, and only the written row tells them apart (DB-SCHEMA §4.5.9).
  outcome: job.valid ? 'ok' : 'failed',
  detail_json: job.detail,
};

return [{ json: {
  row_b64: Buffer.from(JSON.stringify([row])).toString('base64'),
  job: row.job,
  outcome: row.outcome,
  rows_affected: row.rows_affected,
} }];

