// onchain-retention — one `retention.cleanup` row per PASS (§4.5.8, §10.6.1).
//
// This workflow is that event's only writer. One row per pass, not per job: the four job rows in
// `retention_runs` carry the per-job detail, and a second per-job copy here would be the same fact
// in two places.
const plan = $('Plan jobs').first().json;
const outcomes = ['diagnostics.purge', 'request_trace.raw_null', 'request_trace.purge', 'client_usage.purge'].map((key) => ({
  job: key,
  outcome: plan.jobs[key].valid ? 'ok' : 'failed',
}));
const failed = outcomes.filter((o) => o.outcome === 'failed').map((o) => o.job);
const now = Date.now();

const B32 = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
let time = '';
let rest = now;
for (let i = 0; i < 10; i += 1) { time = B32[rest % 32] + time; rest = Math.floor(rest / 32); }
let rand = '';
for (let i = 0; i < 16; i += 1) rand += B32[Math.floor(Math.random() * 32)];

const rowsAffected = {
  'diagnostics.purge': $('Row diagnostics.purge').first().json.rows_affected,
  'request_trace.raw_null': $('Row request_trace.raw_null').first().json.rows_affected,
  'request_trace.purge': $('Row request_trace.purge').first().json.rows_affected,
  'client_usage.purge': $('Row client_usage.purge').first().json.rows_affected,
};

const event = {
  id: time + rand,
  ts: now,
  // `error` when any job refused its window: the severity is the pass's, and a refused window is an
  // operator setting that needs changing, not an informational note.
  severity: failed.length > 0 ? 'error' : 'info',
  event: 'retention.cleanup',
  detail_json: JSON.stringify({ startedAt: plan.startedAt, finishedAt: now, outcomes, failed, rowsAffected }),
  created_at: now,
};
return [{ json: { event_b64: Buffer.from(JSON.stringify([event])).toString('base64'), failed } }];

// onchain-retention — the terminal gate (L-2: a diagnostic nobody reads is not a diagnostic).
//
// `Plan jobs` computes a health signal — which windows were refused — and four tables record it.
// None of those is a READER: a refused window would sit in `retention_runs` looking like a row
// nobody queries, exactly as the snapshotter's `dropped` array did for four days.
//
// This node is that reader. It throws with the job names, and the throw reaches Telegram through
// `errorWorkflow` (`onchain-error-alert`).
//
// **The message names the JOBS and points at the table for the reasons, and that shape was forced
// by a measurement** (task 014-41 acceptance, 2026-08-24). An earlier version carried every reason
// inline, separated by ` | `. n8n splits a Code-node error on the LAST `: ` — head into
// `description`, tail into `message` — and `onchain-error-alert` reads `message`. The delivered
// alert therefore named ONE cause and no job at all, while the full text survived only in the stack
// trace nobody reads. So: no `: ` in this string, the jobs named in it, and the reasons left where
// they are already queryable. L-4 again — a monitoring change is proven by the message ARRIVING,
// and by arriving useful.
//
// **The denominator is 4, not 3, since task 015-19 added `client_usage.purge` as a fourth job**
// (R-7.6, AC-40). Counting from a stale literal here would be the same class of defect as L-2: a
// gate that silently under-reports its own scope.
//
// **Chained, not fanned out beside the writers** (CLAUDE.n8n.md): with `executionOrder: v1` the
// relative order of parallel branches follows node geometry, so a gate that must observe completed
// side effects needs an EDGE. Every upstream node carries `alwaysOutputData` so an empty result
// cannot skip it.
const failed = $('Pass event').first().json.failed ?? [];
if (failed.length > 0) {
  const startedAt = $('Plan jobs').first().json.startedAt;
  throw new Error(
    `onchain-retention refused ${failed.length} of 4 windows and deleted nothing for them — ` +
      `${failed.join(', ')}. Each refusal is recorded in onchain.retention_runs.detail_json for ` +
      `started_at=${startedAt}. The windows live in the "Set Parameters" node (§10.3.1).`,
  );
}
return [{ json: { ok: true, jobs: 4 } }];
